    "titre": "Splendor Paternae gloriae – T.O.",
    "paroles": "Saint Ambroise\nSplendeur de la gloi re du Père,\nLumière d’où jaillit la lumière,\nLumière et source de Lumière\nEt jour illuminant le Jour.\nViens à nous, soleil véritable,\nÉtincelant pour tous les siècles\nPénètre nos intelligences\nDes rayons de ton Esprit saint\nInvoquons maintenant le Père,\nLe Père de gloire éternelle,\nLe Père de grâce puissante ;\nQu’il nous préserve de tomber.\nQu'il dirige toutes nos forces,\nBrise les dents de l' Adversaire;\nDans l'épreuve, qu'il nous soutienne,\nDonne sa grâce pour agir.\nQu’il gouverne et guide nos âmes\nEn des corps chastes et fidèles ;\nQue notre foi brûle, fervente,\nBien loin des poisons du Menteur.\nQue le Christ nous soit nourriture,\nQue la foi soit notre breuvage ;\nQue nous goûtions, pleins d'allégresse,\nLa sobre ivresse de l'Esprit.\nQue ce jour passe dans la joie,\nComme l'aurore, soyons chastes\nNotre foi soit le plein midi\nEt nos cœurs loin du crépuscule.\nLaudes\n59. Psaume 94 : Psaume invitatoire\nVenez, crions de joie pour le Seigneur,\nAcclamons notre rocher, notre salut !\nAllons jusqu’à lui en rendant grâce,\nPar nos hymnes de fête, acclamons -le !\nOui, le grand Dieu, c’est le Seigneur,\nLe grand roi au-dessus de tous les dieux ;\nIl tient en main les profondeurs de la terre,\nEt les sommets des montagn es sont à lui ;\nA lui la mer c’est lui qui l’a faite,\nEt les terres car ses mains les ont pétries.\nEntrez, inclinez-vous, prosternez-vous,\nAdorons le Seigneur qui nous a faits.\nOui, il est notre Dieu ; +\nNous sommes le peuple qu’il conduit,\nLe troupeau guidé par sa main.\nAujourd’hui, écouterez -vous sa parole ? +\n« Ne fermez pas votre cœur comme au désert,\nComme au jour de tentation et de défi,\nOù vos pères m’ont tenté et provoqué,\nEt pourtant ils avaient vu mon exploit.\nQuarante ans leur génération m’a déçu, +\nEt j’ai dit : Ce peuple a le cœur égaré,\nIl n’a pas connu mes chemins.\nDans ma colère, j’en ai fait le serment :\nJamais ils n’entreront dans mon repos. »\n60. Psaume 99 : Psaume invitatoire\nEntrée au Temple\nAcclamez le Seigne ur, terre entière,\nservez le Seigneur dans l'allégresse,\nvenez à lui avec des cha nts de joie !\nReconnaissez que le Seigne ur est Dieu :\nil nous a faits, et nous s ommes à lui,\nnous, son peuple, son troupeau.\nVenez dans sa mais on lui rendre grâce,\ndans sa demeure chant er ses louanges ;\nrendez-lui grâce et bénissez son nom !\nOui, le Seigneur est bon,\néternel est son amour,\nsa fidélité demeure d'âge en âge.",
