    "id": "songbook-64",
    "titre": "Hymne - Commun des Apôtres",
    "paroles": "Que la louange exulte au ciel,\nQue la joie réponde sur terre !\nCar c’est la gloire des Apôtres\nQue nous célébrons aujourd’hui.\nVous, les justes juges des hommes\nEt les vraies lumières du monde,\nVoici les vœux de notre cœur ;\nEcoutez nos voix suppliantes.\nPuisque santé et maladies\nObéissent à vos paroles,\nGuérissez notre cœur malade,\nA notre âme rendez vigueur.\nAinsi, quand revien dra le Christ\nPour juger, à la fin des temps,\nIl nous fera participer\nAu bonheur qui n’a pas de fin.\nGloire et louange soient à notre Dieu\nQui nous donne par vous la grâce\nD’être formés à l’Evangile\nEt de chercher les biens du ciel.\n2. Vous les cieux …\nEt vous les eaux dessus le ciel …\nEt toutes les puissances du Seigneur …\n3. Et vous la lune et le soleil …\nEt vous les astres du ciel …\nVous toutes, pluies et rosées …\n4. Vous tous, souffles et vents …\nEt vous le feu et la chal eur …\nEt vous la fraîcheur et le froid …\n5. Et vous les nuits et les jours …\nEt vous les ténèbres, la lumière …\nEt vous les éclairs, les nuées …\n6. Et vous montagnes et collines …\nEt vous les plantes de la terre …\nEt vous sources et fontaines …\n7. Et vous rivières et océans …\nVous tous bêtes et troupeaux …\nVous tous oiseaux dans le ciel …\n8. Vous les enfants des hommes …\nLes esprits et les âmes des justes …\nLes saints et les humbles de cœur …",
