    "titre": "Hymne - Commun des martyrs.",
    "paroles": "Puissance et gloire de l'Esprit W14\n1. Puissance et gloire de l'Esprit:\nHeureux les vrais martyrs !\nLa chair dont Dieu les a pétris\nEn lui pourra surgir.\n2. Pareil aux grains qui sont broyés\nPour être notre pain,\nLeur corps se joint au C orps brisé\nQui s'offre par nos mains.\n3. Leur sang se mêle au Sang s auveur\nQui lave nos péchés.\nIls sont l'amour du même C œur\nQui nous a tant aimés.\n4. Heureux qui donne sans compter\nJusqu'à sa propre chair !\nIl trouve en Dieu sa liberté,\nVisage découvert.\n5. La chair est vaine sans l'Esprit\nEt cendre dans la mort.\nPar votre croix, Seigneur, survit\nLa gloire de nos corps.\n6. Dans vos martyrs, c'est vous qu'on tue,\nMais vous qu'on glorifie ;\nCar votre Eglise en eux salue\nLa force de l'Esprit.\n7. Le grain survit dans la m oisson,\nAu jour de votre jour ;\nLa vie, la mort n'ont plus de nom\nAu règne de l'amour.",
