    "paroles": "En plein cœur de l’Eglise le Seigneur l’ appela\nPour porter sa Parole il lui donna l’Es prit,\nLe combla de sagesse, de gloire le vêtit\nEt sur lui fit descendre allégresse et bonh eur.\nAux sources d’Evangile le Seigneur le mena,\nLe planta comme un arbre près des eaux du sa lut.\nLui donna sans mesure la sève du savoir,\nLui fit en abondance porter des fruits de choix .\nDu trésor de ses grâces le Seig neur l’instruisit,\nDans la nouvelle Alliance lui enseigna sa loi.\nIl lui donna d’en vivre avec fi délité,\nPuis d’enseigner l’Eglise avec humili té.\nDans la vie éternelle le Seigneur le reçut,\nLui découvrit sa face qu’il avait tant cher chée,\nLui donna connaissance des mystères cachés\nEt la joie bienheureuse de voir la Véri té.\nL’aurore apporte sa lumière\nQu'elle paraisse toute entière\nComme le Fils tout à son Père\nEt tout entier le Père au Fils.",
