    "titre": "Psaume 62. Soif de Dieu",
    "paroles": "Dieu, tu es mon Dieu, je te cherche dès l'aube : *\nMon âme a soif de toi ;\nAprès toi languit ma chair,\nTerre aride, altérée, sans eau.\nJe t'ai contemplé au sanctuaire,\nJ’ai vu ta force et ta gloire.\nTon amour vaut mie ux que la vie :\nTu seras la louange de mes lèvres !\nToute ma vie je vais te bénir,\nLever les mains en invoqu ant ton nom.\nComme par un festin je ser ai rassasié ;\nLa joie sur les lèvres, je dir ai ta louange.\nDans la nuit, je me souvi ens de toi\nEt je reste des heures à te parler.\nOui, tu es venu à mon secours :\nJe crie de joie à l'ombre de tes ailes.\nMon âme s'attache à toi,\nTa main droite me soutient.",
