    "titre": "Psaume 149. Louange triomphale",
    "paroles": "Chantez au Seigne ur un chant nouveau,\nlouez-le dans l'assemblée de ses fidèles !\nEn Israël, joie pour son créateur ;\nDans Sion, allégresse pour son Roi !\nDansez à la louange de son nom,\nJouez pour lui, tambour ins et cithares !\nCar le Seigneur aime son peuple,\nIl donne aux humbles l 'éclat de la victoire.\nQue les fidèles exultent, glorieux,\nCriant leur joie à l'he ure du triomphe.\nQu'ils proclament les él oges de Dieu,\nTenant en main l'épée à deux tranchants.\nTirer vengeance des nations,\nInfliger aux peuples un châtiment,\nCharger de chaînes les rois,\nJeter les princes dans les fers,\nLeur appliquer la sent ence écrite,\nC'est la fierté de ses fidèles.\nPsaume 150 n° 202 p. 117\nPsaume 117 n° 114 p. 77",
