    "titre": "NT2 Cantique de Zacharie (Lc 1, 68-79)",
    "paroles": "Béni soit le Seigneur, le Die u d'Israël,\nQui visite et rachète son peuple.\nIl a fait surgir la force qui nous sauve\nDans la maison de Dav id, son serviteur,\nComme il l'avait dit par la bo uche des saints,\nPar ses prophètes, depuis les t emps anciens :\nSalut qui nous arrache à l'ennemi,\nA la main de tous nos oppresseurs,\nAmour qu'il montre envers nos pères,\nMémoire de son Alliance sainte,\nSerment juré à notre p ère Abraham\nDe nous rendre sans crainte,\nAfin que délivrés de la main des ennemis +\nNous le servions dans la just ice et la sainteté,\nEn sa présence, tout au long de nos jours.\nToi aussi, petit enfant , tu seras appelé\nprophète du Très-Haut : *\nTu marcheras devant, à la face du Seigneur,\nEt tu prépareras ses chemins\nPour donner à son peuple de conn aître le salut\nPar la rémission de ses péchés,\nGrâce à la tendresse, à l'amo ur de notre Dieu,\nQuand nous visite l'astre d'en haut,\nPour illuminer ceux qui habitent les ténèbres\nEt l'ombre de la mort, *\nPour conduire nos pas au chemin de la paix.\nVêpres",
