    "id": "songbook-72",
    "titre": "Hymne lumière, origine et source - TO",
    "paroles": "Lumière, origine et source de la lumière,\nÔ Dieu très bon, sois favo rable à nos prières\nRepousse au loin l'obscuri té de nos péchés,\nEmbellis-nous de ta lumière.\nVoici qu'est achevé le la beur de ce jour,\nDe par ta volonté nous sommes sains et saufs ;\nVois, de tout notre cœur nous te di sons merci,\nDès maintenant et pour toujours.\nLe coucher du soleil ra mène la ténèbre,\nMais qu'il brille pour nous l'étince lant soleil\nQui embrase là-haut, de sa lumière d'or,\nLa multitude des saints anges.\nTout ce que la journée a pu ca cher de fautes,\nQue le Christ indulgent et très bon le détruise ;\nAlors un pur éclat fera luire nos cœurs\nAu plus profond de cet te nuit.\nLouange à toi, le Père, et gloire à toi , le Fils,\nSemblable seigneurie à leur Souffle très saint,\nÔ vous qui gouvernez avec autorité\nLe monde à travers tous les siècles.\nIl règne, le Seigneur,\nNotre Dieu tout-puissant, Alléluia !\nExultons, crions de joie,\nEt rendons-lui la gloire ! Alléluia !\nCar elles sont venues\nLes Noces de l'Agneau, Alléluia !\nEt pour lui son épouse\nA revêtu sa parure. Alléluia !",
