    "id": "songbook-76",
    "titre": "Psaume 113A. Les merveilles de Dieu",
    "paroles": "Quand Israël sortit d'Egypte,\nEt Jacob, de chez un pe uple étranger,\nJuda fut pour Dieu un sanctuaire,\nIsraël devint son domaine.\nLa mer voit et s'enfuit,\nLe Jourdain retourne en arrière.\nComme des béliers, bond issent les montagnes,\nEt les collines, comme des agneaux.\nQu'as-tu, mer, à t'enfuir,\nJourdain, à retourn er en arrière ?\nMontagnes, pourquoi bond ir comme des béliers,\ncollines, comme des agneaux ?\nTremble, terre, devant le Maître,\nDevant la face du Dieu de Jacob,\nLui qui change le roch er en source\nEt la pierre en fontaine !",
    "langue": "fr",
    "categorie": "psaume",
    "temps_liturgique": "toute_annee",
    "statut_juridique": "autorisation_obtenue",
