    "id": "songbook-82",
    "titre": "NT3 Cantique de Siméon (Lc 2, 29-32)",
    "paroles": "Antienne : Sauve -nous Seigneur, quand nous\nveillons ; garde- nous quand nous dormons. Et nous\nveillerons avec le Christ, et nous reposerons en paix.\nMaintenant, ô Maître souverain, +\nTu peux laisser ton servite ur s'en aller\nEn paix, selon ta parole.\nCar mes yeux ont v u le salut\nQue tu préparais à la face des peuples\nLumière qui se rév èle aux nations\nEt donne gloire à ton pe uple Israël.\n6.\n- Chants d’entrée\n- Chants de sortie\n- Chants de\nlouange\n- Hymnes",
