    "id": "songbook-107",
    "titre": "Acclamez Dieu toute la terre IEV 502",
    "paroles": "Alléluia, alléluia, alléluia, alléluia\n1. Acclamez Dieu toute la terre\nServez-le dans l’allégresse\nAllez à lui avec des chants de joie\nCar éternel est son amour\n2. Lui, le Seigneur est notre Dieu\nNous, le troupeau de son bercail.\nIl nous a faits et nous sommes à lui\nCar éternel est son amour.\n3. Son Royaume est là, son Évangile est proclamé.\nNous annonçons le Christ Ressuscité.\nJubilons pour lui !",
