    "id": "songbook-146",
    "titre": "Danse de joie IEV 518",
    "paroles": "Danse de joie, danse pour ton Dieu,\nDanse la ronde de sa joie. (bis)\n1. Comme David devant l’arche de Dieu,\nDansons pour le Seigneur,\nIl est déjà au milieu de nous, le Royaume de Dieu.\n2. Comme Marie chez Elisabeth, j’exulte de joie,\nCar le Seigneur habite en moi et chante Alléluia.\n3. Comme les bergers à Bethléem, glorifions le Seigneur.\nNous avons vu et entendu les merveilles de Dieu.",
