    "titre": "Hosanna IEV 10-15",
    "paroles": "Hosanna, hosanna,\nHosanna au plus haut des cieux (bis)\n1. Je veux chanter ton nom, proclamer ton amour,\nAnnoncer que tu es Seigneur\nHosanna au plus haut des cieux.\n2. Loué, exalté, Glorifié soit le Roi des rois (bis)",
