    "id": "songbook-245",
    "titre": "Rends-nous la joie de ton salut G268",
    "paroles": "1° dimanche de Carême A B C Jésus au désert\n1. Rends-nous la joie de ton salut, que ton jour se lève (bis)\nDonne-nous ton pardon, lave-nous de tout péché,\nDonne-nous ta grâce.\n2. Dieu voulut vivre notre vie, être en tout semblable. (bis)\nComme nous, au désert, Dieu éprouve dans son corps\nToutes nos misères.\n3. Christ au désert connut nos faims et nos solitudes. (bis)\nDu péché, il voulut éprouver nos tentations :\nDemandons sa force.\n3. Il a fait les grands luminaires, car …\nLe soleil pour gouverner sur le jour , car …\nLa lune et les étoiles sur la nuit, car …\n4. Il frappa les premiers -nés des Egyptiens, car …\nEt d’Egypte fit sortir Israël , car …\nA main forte et à bras étendu , car …\n5. Il fendit la mer Rouge en deux parts, car …\nEt fit passer Israël en son milieu , car …\nY culbutant Pharaon et son armée, c ar …\n6. Il mena son peuple au désert, car …\nIl frappa des princes puissants, car …\nFit périr des rois redoutables, car …\n7. Il donna leur terre en héritage, car …\nEn héritage à Israë l son serviteur, car …\nIl se souvint de son peuple oublié, car …\n8. Il nous sauva de la main des oppresseurs, car …\nA toute chair, il donne le pain, car …\nRendez grâce au Dieu du Ciel, Amen ! Car …",
