    "id": "songbook-246",
    "titre": "Resucito, resucito Kiko Arguello",
    "paroles": "Resucito, Resucito, Resucito, Aleluya !\nAleluya, Aleluya, Aleluya, Resucito !\n1. La muerte, donde esta la muerte ?\nDonde esta mi muerte ? Donde su victoria ?\n2. Alegria, alegria hermanos,\nQue si hoy nos queremos, Es porque r esucito.\n3. Si con El morimos, Con El vivimos,\nCon El cantamos. Aleluya !",
