    "id": "songbook-249",
    "titre": "Si le Père vous appelle T154",
    "paroles": "1. Si le Père vous appelle à aimer comme il vous aime,\nDans le feu de son Esprit, Bienheureux êtes-vous !\nSi le monde vous appelle à lui rendre une espérance,\nÀ lui dire son salut, Bienheureux êtes-vous !\nSi l'Église vous appelle à peiner pour le Royaume,\nAux travaux de la moisson, Bienheureux êtes-vous !\nTressaillez de joie ! Tressaillez de joie !\nCar vos noms sont inscrits\nPour toujours dans les cieux !\nTressaillez de joie ! Tressaillez de joie !\nCar vos noms sont inscrits dans le cœur de Dieu !\n2. Si le Père vous appelle à la tâche des Apôtres,\nEn témoins du seul Pasteur, Bienheureux êtes-vous !\nSi le monde vous appelle à l'accueil et au partage\nPour bâtir son unité, Bienheureux êtes-vous !\nSi l'Église vous appelle à répandre l'Évangile\nEn tout point de l'univers, Bienheureux êtes-vous !\n3. Si le Père vous appelle à quitter toute richesse\nPour ne suivre que son Fils, Bienheureux êtes-vous !\nSi le monde vous appelle à lutter contre la haine\nPour la quête de la Paix, Bienheureux êtes-vous !\nSi l'Église vous appelle à tenir dans la prière,\nAu service des pécheurs, Bienheureux êtes-vous !\n6. « Si l’un de vous me veut servir, qu’enfin il me suive (bis)\nOù je suis, il sera, il partagera l’amour\nQue mon Père donne.\n5° dimanche C L’avènement du monde nouveau\n1. Rends-nous la joie de ton salut, que ton jour se lève (bis)\nDonne-nous ton pardon, lave-nous de tout péché,\nDonne-nous ta grâce.\n2. Les derniers temps vont s’achever, Dieu vers nous\ns’avance (bis)\nCar son jour va lever bientôt toute obscurité,\nEclairer la terre.\n3. Oui, l’ancien monde va crouler : jour d’effroi, de crainte (bis)\nEt l’éclat du Seigneur enfin brillera pour t ous,\nRéchauffant les hommes.\n4. Oui, c’est la mort de Jésus-Christ qui nous renouvelle (bis)\nCar voici que par Lui, Dieu, tu viens remplir nos vies,\nHabiter les hommes.\n5. Dieu, sans toi l’homme ne pourrait fair e\nUn nouveau monde (bis)\nCar toi seul peut sauver l’homme qui ne s’aime plus,\nToi qui nous rassembles.\n6. Oui, soyons prêts quand reviendra Christ en toute gloire (bis)\nChaque jour, hâtons -nous, préparons la paix de Dieu\nDans le cœur des hommes.",
    "langue": "fr",
    "categorie": "louange",
    "temps_liturgique": "toute_annee",
    "statut_juridique": "autorisation_obtenue",
