    "id": "songbook-327",
    "titre": "Face adorable de Jésus IEV 13-15",
    "paroles": "Face adorable de Jésus, Face adorable de Jésus\nContrechant soliste :\n1. Ô visage de l’Agneau, ô cœur ouvert, ô ma blessure,\nÔ ma source et mon bonheur, ô visage de l’agneau.\n2. Ô visage de l’Amour, ô cœur meurtri, ma guérison,\nÔ chair de Dieu immaculée, ô visage de l’Amour.",
