    "id": "songbook-328",
    "titre": "Fixe ton regard sur Jésus Fr. J.-B.",
    "paroles": "Fixe ton regard sur Jésus et désire imiter ton Seigneur.\nIl t’embrasera de son feu.\nIl comblera ton cœur de son amour.\nMon Dieu, mon Dieu et mon tout.\nÔ mon Dieu, c’est toi mon tout,\nÔ mon Dieu et mon tout.",
