    "id": "songbook-331",
    "titre": "Grain de blé IEV10-14",
    "paroles": "1. Grain de blé qui tombe en terre, si tu ne meurs pas,\nTu resteras solitaire, ne germeras pas.\n2. Qui à Jésus s'abandonne, trouve la vraie vie.\nHeureux l’homme qui se donne, il sera béni.",
