    "id": "songbook-349",
    "titre": "Jésus, le Christ J. Berthier Taizé",
    "paroles": "Jésus, le Christ, lumière intérieure,\nNe laisse pas mes ténèbres me parler.\nJésus, le Christ, lumière intérieure,\nDonne-moi d’accueillir ton amour.",
