    "titre": "Prosternez-vous IEV 14-36",
    "paroles": "Prosternez-vous devant votre Roi,\nAdorez-le de tout votre cœur,\nFaites monter vers sa majesté\nDes chants de gloire pour votre Roi des rois !",
