    "id": "songbook-509",
    "titre": "Jésus, toi qui as promis IEV 14-20",
    "paroles": "Jésus, toi qui as promis d'envoyer l'Esprit\nÀ ceux qui te prient, ô Dieu,\nPour porter au monde ton feu\nVoici l'offrande de nos vies.",
