    "id": "songbook-516",
    "titre": "Ô Esprit du Dieu vivant IEV 149",
    "paroles": "Ô Esprit du Dieu vivant, viens toucher mon cœur (bis)\nPrends-moi, guide-moi en ton Amour.\nÔ Esprit du Dieu vivant, viens toucher mon cœur.\nÔ Esprit du Dieu vivant, sois le maître en moi (bis)\nSonde-moi, guide-moi en ton Amour.\nÔ Esprit du Dieu vivant, sois le maître en moi.\nParoles originales de D. Iverson :\nSpirit of the living God, fall afresh on me.\nMelt me, mould me, fill me, use me.\nSpirit of the living God, fall afresh on me.",
