    "titre": "Veni Sancte Spiritus Taizé",
    "paroles": "Veni Sancte Spiritus, tui amoris ignem accende,\nVeni Sancte Spiritus, veni Sancte Spiritus .\nTraduction : Viens Esprit Saint, allume en nous le Feu\nde ton Amour, viens Esprit Saint, viens Esprit Saint.\nNB : le Veni Sancte Spiritus en français est au n°44 page\n41 ; il est aussi chanté au n°532.",
