    "id": "songbook-601",
    "titre": "Alma Redemptoris Mater",
    "paroles": "Alma Redemptóris Mater,\nQuae pérvia caéli pórta mánes,\nEt stélla máris, succúrre cadénti, Súrgere qui cúrat\npópulo : Tu quae genuísti, natúra miránte,\nTúum sánctum Genitórem :\nVirgo prius ac postérius, Gabriélis ab óre\nsúmens íllud Ave, peccatórum miserére.",
