    "titre": "Je suis tout à toi, Marie IEV 531",
    "paroles": "Je suis tout à toi, Marie, Vierge sainte\nTout ce que j'ai est tien, Marie, vierge pure,\nSois mon guide en tout, Marie, notre mère.",
