    "id": "songbook-633",
    "titre": "Regina caeli",
    "paroles": "Traduction : Reine du ciel, réjouis-toi, alléluia,\nCar le Seigneur que tu as porté, alléluia,\nEst ressuscité comme il l’avait dit, alléluia,\nReine du ciel, prie Dieu pour nous, alléluia.",
