    "id": "songbook-719",
    "titre": "Qui est le Roi ? IEV Enfants",
    "paroles": "Qui est le Roi de la jungle ?\nQui est le Roi de la mer ?\nQui est le Roi de tout l’Univers ?\nQui est mon Roi à moi ?\nC’est lui : J.E.S.U.S. (dit : ) Jésus !\nIl est le Roi de mon cœur.\nIl est le Roi de tout l’Univers,\nDe la jungle et la mer !",
